// Creative Problem Solving Practice Test 2. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items: decision traps, idea generation and formal logic.
import {q, mix} from './q.js';
const MV='McShane & Von Glinow, Organizational Behavior', AD='Adair, Decision Making & Problem Solving', ST='Sternad, Solve It!', TH='Thinknetic, Critical Thinking & Logic Mastery';
const CRIT='Critical & Effective Thinking', PS='Problem Solving Strategies & Skills', GEN='Clarification of Problems & Generating Ideas', CON='Examining Constraints/Developing Alternatives', LOG='Components of Logic';

export default {
 id:'creative-problem-solving-2',
 event:'Creative Problem Solving',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'McShane & Von Glinow’s Organizational Behavior, Adair’s Decision Making & Problem Solving, Sternad’s Solve It! and Thinknetic’s Critical Thinking & Logic Mastery',
 plan:[{area:CRIT,weight:26},{area:PS,weight:24},{area:GEN,weight:10},{area:CON,weight:20},{area:LOG,weight:20}],
 questions:mix([
  q(CRIT,'A close-knit team never voices doubts because members value agreement over critical evaluation. What is this?','Groupthink',['Social loafing','Brainstorming','Synergy'],'A','Groupthink occurs when the desire for harmony overrides realistic appraisal of alternatives, so flawed decisions go unchallenged.',MV),
  q(CRIT,'A clinic manager is 95% sure a project will finish in 2 weeks; it takes 6. Which two biases most likely contributed?','Overconfidence and planning fallacy',['Anchoring and the halo effect','Hindsight and the framing effect','Recency and the bandwagon effect'],'B','People tend to overrate the accuracy of their judgments and underestimate how long tasks will take, even when past projects ran late.',MV),
  q(CRIT,'A student cannot think to use a coin as a screwdriver because a coin is “for buying things.” What barrier is this?','Functional fixedness',['Confirmation bias','Satisficing','Escalation of commitment'],'C','Functional fixedness is the tendency to see objects only in their usual role, which blocks creative uses of available resources.',ST),
  q(CRIT,'An interviewer rates a well-dressed candidate highly on every skill without evidence. Which error is this?','Halo effect',['Contrast effect','Recency effect','Primacy effect'],'D','The halo effect lets one positive trait shape judgments of unrelated traits, so evaluations stop reflecting actual evidence.',MV),
  q(CRIT,'A person assumes a quiet, bookish stranger is a librarian rather than a salesperson, ignoring that salespeople are far more common. What is this?','Representativeness heuristic',['Availability heuristic','Anchoring and adjustment','Status quo bias'],'A','Judging likelihood by how well something matches a stereotype ignores base rates—how common each category actually is.',TH),
  q(CRIT,'Ice cream sales and drowning deaths both rise in summer. What is the best conclusion?','A third factor, hot weather, likely drives both',['Ice cream consumption causes drowning','Drowning causes people to buy ice cream','The data must have been recorded incorrectly'],'B','Correlation does not prove causation. A confounding variable—hot weather increasing both swimming and ice cream sales—explains the link.',TH),
  q(CRIT,'In dual-process theory, which system is fast, automatic and intuitive?','System 1',['System 2','System 3','System 0'],'C','System 1 thinking is quick and effortless but prone to bias; System 2 is slow, deliberate and analytical, and can check System 1.',MV),
  q(CRIT,'Why might a team assign one member to play “devil’s advocate” during a decision?','To challenge assumptions and expose weaknesses',['To speed up agreement among all members','To make the final decision for the group','To record the minutes of the discussion'],'D','A devil’s advocate deliberately argues the opposing view, reducing groupthink and helping the team test the plan before committing.',MV),
  q(CRIT,'Which is a primary source for a study’s findings?','The original peer-reviewed research article',['A news story summarizing the study','A blog post quoting a news story','A textbook chapter citing many studies'],'A','A primary source reports original research directly. Secondary sources summarize or interpret it and can add errors or spin.',TH),
  q(CRIT,'People feel losing $50 more strongly than gaining $50. What is this tendency called?','Loss aversion',['Sunk cost fallacy','Optimism bias','Anchoring'],'B','Loss aversion means losses weigh more heavily than equal gains, which can make people avoid reasonable risks or cling to the status quo.',MV),
  q(CRIT,'Which trait best shows intellectual humility in a critical thinker?','Willingness to revise views when evidence changes',['Refusal to discuss ideas with those who disagree','Confidence that first impressions are always right','Preference for sources that agree with them'],'C','Intellectual humility means recognizing the limits of one’s knowledge and updating beliefs when better evidence or arguments appear.',TH),
  q(CRIT,'A business book studies only highly successful companies to find the “secrets” of success. What flaw might affect its conclusions?','Survivorship bias',['Framing effect','Availability bias','Halo effect'],'D','Ignoring failed companies that used the same practices can make those practices look like causes of success when they may not be.',TH),
  q(CRIT,'What is the difference between an assumption and a fact?','An assumption is accepted without proof',['An assumption is always proven false','A fact is any widely held opinion','There is no meaningful difference'],'B','Critical thinkers identify assumptions—beliefs taken for granted—and test them, since a false assumption can undermine an entire argument.',TH),
  q(PS,'In the Plan–Do–Check–Act cycle, what happens in the “Check” step?','Results are measured against the expected outcome',['The new process is permanently adopted','The problem is first identified and defined','The team brainstorms new ideas to test'],'A','PDCA plans a change, tests it on a small scale, checks results against predictions, then acts by adopting, adjusting or abandoning it.',ST),
  q(PS,'A hospital keeps replacing a leaking pipe that fails every month without finding out why. What is the main error?','Treating a symptom, not the root cause',['Using too many problem-solving tools','Involving too many stakeholders','Setting goals that are too specific'],'B','Repeatedly fixing symptoms lets the underlying cause persist. Root cause analysis looks for why the problem keeps recurring.',ST),
  q(PS,'In a SWOT analysis, which factors are internal to the organization?','Strengths and weaknesses',['Opportunities and threats','Threats and weaknesses','Opportunities and strengths'],'C','Strengths and weaknesses are internal; opportunities and threats come from the external environment, such as markets or regulations.',AD),
  q(PS,'What is the main purpose of a process flowchart in problem solving?','To show steps in sequence and reveal delays',['To rank options by cost and benefit','To list the root causes of a problem','To schedule each team member’s tasks'],'D','Mapping a process step by step exposes bottlenecks, redundant steps and handoffs where errors or delays occur.',ST),
  q(PS,'A problem solver compares the current state with the goal and takes steps to reduce the difference. What strategy is this?','Means–ends analysis',['Trial and error','Working backward','Random search'],'A','Means–ends analysis breaks the gap between the present and goal states into sub-goals and chooses actions that close each gap.',TH),
  q(PS,'A planner starts from the desired event date and schedules tasks in reverse. What strategy is this?','Working backward',['Means–ends analysis','Hill climbing','Brainstorming'],'B','Working backward begins at the goal and determines what must happen just before it, which is useful when the end state is clear.',TH),
  q(PS,'Which tool shows project tasks as bars along a timeline?','Gantt chart',['Pareto chart','Fishbone diagram','Scatter plot'],'C','A Gantt chart shows each task’s start, duration and overlap, helping teams plan, sequence work and track progress.',ST),
  q(PS,'According to McShane and Von Glinow, which type of decision follows established routines for recurring problems?','Programmed decision',['Nonprogrammed decision','Intuitive decision','Escalated decision'],'D','Programmed decisions use standard procedures for routine problems; nonprogrammed decisions require new solutions for novel ones.',MV),
  q(PS,'In hypothesis-driven problem solving, what does the solver do first?','States a likely answer and then tests it with data',['Collects all possible data before forming ideas','Votes on solutions before defining the issue','Implements a solution and waits for feedback'],'A','Starting with a testable hypothesis focuses analysis on what matters, and the hypothesis is revised or rejected as evidence comes in.',ST),
  q(PS,'A team borrows the pit-crew routines of auto racing to speed up operating room turnover. What strategy is this?','Reasoning by analogy',['Working backward','Means–ends analysis','Trial and error'],'B','Analogical thinking transfers a solution from a different field with a similar structure, often producing creative breakthroughs.',ST),
  q(PS,'Which question set helps define a problem by asking who, what, when, where, why and how?','5W1H',['SCAMPER','SMART','SWOT'],'C','The 5W1H questions clarify the problem’s scope and context so the team solves the right problem with a shared understanding.',AD),
  q(PS,'Which step in Adair’s approach comes immediately after generating possible options?','Evaluating the options against criteria',['Defining the objective of the decision','Collecting information about the problem','Implementing and monitoring the decision'],'D','Adair’s sequence moves from defining objectives and gathering information to generating options, evaluating them, deciding and implementing.',AD),
  q(GEN,'A student writes a central topic in the middle of a page and branches related ideas outward. What technique is this?','Mind mapping',['Nominal group technique','Delphi technique','Force field analysis'],'A','Mind maps capture associations visually and nonlinearly, helping people see connections and generate more ideas.',ST),
  q(GEN,'A team asks, “How could we make patient wait times even worse?” and then reverses each answer. What technique is this?','Reverse brainstorming',['Brainwriting','Mind mapping','The Delphi technique'],'B','Reverse brainstorming identifies ways to cause a problem, then flips them into solutions, which can reveal hidden causes.',ST),
  q(GEN,'In the 6-3-5 method, six people each write three ideas in five minutes and pass them on. What is this technique called?','Brainwriting',['Electronic voting','Reverse brainstorming','Delphi technique'],'C','Brainwriting has members write ideas silently and build on others’ ideas, reducing production blocking and evaluation apprehension.',MV),
  q(GEN,'In de Bono’s Six Thinking Hats, which hat represents creativity and new ideas?','Green hat',['Black hat','White hat','Red hat'],'D','Green stands for creativity; black for caution, white for facts and red for feelings. Blue manages the thinking process and yellow benefits.',ST),
  q(GEN,'After brainstorming, a team narrows many ideas to the single best one. What kind of thinking is this?','Convergent thinking',['Divergent thinking','Lateral thinking','Associative thinking'],'A','Divergent thinking generates many options; convergent thinking evaluates and narrows them to the most promising solution.',ST),
  q(CON,'In a weighted decision matrix, cost has weight 3 and quality weight 2. Option X scores 4 on cost and 5 on quality. What is its total?','22',['18','20','45'],'B','Multiply each score by its weight and add: (4 × 3) + (5 × 2) = 12 + 10 = 22.',AD),
  q(CON,'A risk matrix rates each risk on which two dimensions?','Likelihood and impact',['Cost and duration','Owner and deadline','Benefit and popularity'],'C','Plotting how likely a risk is against how severe its impact would be helps teams decide which risks to address first.',ST),
  q(CON,'In Kepner–Tregoe analysis, what happens to an alternative that fails a “must” criterion?','It is eliminated regardless of other scores',['It receives a lower weighted score','It is kept as a backup option','It is moved to the list of “wants”'],'D','“Musts” are mandatory requirements that screen out alternatives; “wants” are desirable features that are weighted and scored.',AD),
  q(CON,'A hospital spends its budget on a new scanner instead of hiring two nurses. What is the value of the nurses called?','Opportunity cost',['Sunk cost','Fixed cost','Marginal revenue'],'A','Opportunity cost is the value of the best alternative given up when a choice is made, and it should be weighed in every decision.',AD),
  q(CON,'A team checks whether its ranking of options changes if the weights in its decision matrix shift slightly. What is this?','Sensitivity analysis',['Root cause analysis','Pareto analysis','Gap analysis'],'B','Sensitivity analysis tests how robust a decision is. If small changes flip the ranking, the decision needs more scrutiny.',ST),
  q(CON,'A team believes it cannot change a rule, but the rule is only an informal habit. What should the team do?','Challenge the assumed constraint',['Accept the constraint as fixed','Drop the problem completely','Ask the newest member to decide'],'C','Separating real constraints from assumed ones opens up options; many “rules” are habits that can be changed.',ST),
  q(CON,'Option A has a 60% chance of saving $100 and a 40% chance of losing $50. What is its expected value?','$40',['$50','$60','$20'],'D','Expected value multiplies each outcome by its probability and adds them: (0.6 × 100) + (0.4 × −50) = 60 − 20 = $40.',AD),
  q(CON,'Which tool lists the forces pushing for a change and the forces resisting it?','Force field analysis',['Gantt chart','Fishbone diagram','Affinity diagram'],'A','Lewin’s force field analysis shows driving and restraining forces so a team can strengthen supports or reduce resistance.',MV),
  q(CON,'Which grid helps a team decide how closely to involve each stakeholder?','A power–interest grid',['A Gantt chart','A risk register','An affinity diagram'],'B','Stakeholders with high power and high interest are managed closely, while those with low power and low interest are monitored.',ST),
  q(CON,'Which question tests the feasibility of an alternative?','Can we carry it out with our resources?',['Is it the most popular idea?','Was it suggested by the leader?','Has it been discussed the longest?'],'C','Feasibility asks whether an option can be done with available time, money, people, skills and legal permission.',AD),
  q(LOG,'What is the converse of “If a patient has a fever, then the patient is ill”?','If the patient is ill, then the patient has a fever',['If the patient has no fever, then the patient is not ill','If the patient is not ill, then the patient has no fever','The patient has a fever and is not ill'],'D','The converse swaps the parts (if Q then P). It is not logically equivalent to the original; only the contrapositive is.',TH),
  q(LOG,'“If it snowed, school closed. School closed. So it snowed.” Which fallacy is this?','Affirming the consequent',['Denying the antecedent','Modus tollens','Modus ponens'],'A','School could close for other reasons. Inferring the “if” part from the “then” part is the formal fallacy of affirming the consequent.',TH),
  q(LOG,'“If P, then Q. Not Q. Therefore, not P.” What form of valid argument is this?','Modus tollens',['Modus ponens','Affirming the consequent','Disjunctive syllogism'],'B','Modus tollens denies the consequent to conclude the antecedent is false. Modus ponens affirms P to conclude Q.',TH),
  q(LOG,'“This medicine works because it is effective.” Which fallacy is this?','Circular reasoning',['False dilemma','Red herring','Slippery slope argument'],'C','The conclusion simply restates the premise, so the argument assumes what it is trying to prove (begging the question).',TH),
  q(LOG,'“A famous actor says this vitamin prevents cancer, so it must be true.” Which fallacy is this?','Appeal to authority',['Hasty generalization','Circular reasoning','Straw man'],'D','Citing someone who lacks expertise on the topic does not provide evidence; claims need support from qualified sources and data.',TH),
  q(LOG,'After two rude customers, an employee concludes that all customers are rude. Which fallacy is this?','Hasty generalization',['Post hoc reasoning','Appeal to emotion','Red herring'],'A','Drawing a broad conclusion from a small or unrepresentative sample is a hasty generalization.',TH),
  q(LOG,'What makes a deductive argument sound?','It is valid and all its premises are true',['It is persuasive to most listeners','It has more than two premises','Its conclusion is widely accepted'],'B','A valid argument’s conclusion follows from its premises; a sound argument is valid and also has true premises.',TH),
  q(LOG,'Asked about rising costs, a manager starts talking about a rival hospital’s parking problems. Which fallacy is this?','Red herring',['Straw man','Bandwagon','False dilemma'],'C','A red herring distracts from the issue with an irrelevant topic, so the original question is never answered.',TH),
  q(LOG,'“All nurses are caregivers. Some caregivers are volunteers. So some nurses are volunteers.” Is the argument valid?','No, the conclusion does not follow',['Yes, it is a valid syllogism','Yes, because both premises are true','No, because nurses cannot volunteer'],'D','The volunteers among caregivers may not include any nurses, so the conclusion is not guaranteed even if the premises are true.',TH),
  q(LOG,'What is the logical negation of “All patients were seen”?','At least one patient was not seen',['No patients were seen','Every patient was seen late','Most patients were seen'],'A','The negation of “all are” is “at least one is not.” “No patients were seen” is a stronger claim than the negation requires.',TH)
 ],4230)
};
